        + wk + ['Calendar:'] + cal)

    _d = nextbd(today)
    vars['next_business_day'] = iso(_d)
    vars['next_business_day_say'] = full(_d)
    cb_lines = []
    cb_days = []
    nowhm = now.strftime('%H:%M')
    cb_list = []
    try:
        cb_list.append(('THE NEXT BUSINESS DAY', nextbd(today)))
    except Exception:
        pass
    for label, dd in cb_list:
