try:
    import json, re
    prods = vars.get('products')
    if isinstance(prods, str):
        try:
            prods = json.loads(prods)
        except Exception:
            prods = None
    if isinstance(prods, dict):
        prods = [prods]
    if not isinstance(prods, list) or not prods:
        found = dict()
        for k in list(vars.keys()):
            m = re.search(r'products\.(\d+)\.(\w+)$', str(k))
            if m:
                found.setdefault(int(m.group(1)), dict())[m.group(2)] = vars.get(k)
        prods = [found[i] for i in sorted(found)]
    def num(x):
        try:
            return float(x)
        except Exception:
            return 0.0
    def money(x):
        x = float(x)
        return ('%d' % x) if x == int(x) else ('%.2f' % x)
    import datetime
    HOL = set(['2026-11-06', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    WEEKEND = set([5, 6])
    raw_now = str(vars.get('now') or '')
    try:
        now = datetime.datetime.fromisoformat(raw_now.strip()[:16].replace(' ', 'T'))
    except Exception:
        now = datetime.datetime.fromisoformat(raw_now.strip()[:10] + 'T00:00')
    today = now.date()
    def iso(d):
        return d.isoformat()
    def parse_iso(s):
        return datetime.date.fromisoformat(str(s)[:10])
    def isbd(d):
        return d.weekday() not in WEEKEND and d.isoformat() not in HOL
    def nextbd(d):
        d = d + datetime.timedelta(days=1)
        while not isbd(d):
            d = d + datetime.timedelta(days=1)
        return d
    def prevbd(d):
        d = d - datetime.timedelta(days=1)
        while not isbd(d):
            d = d - datetime.timedelta(days=1)
        return d
    def add_bd(d, n):
        k = 0
        while k < n:
            d = d + datetime.timedelta(days=1)
            if isbd(d):
                k += 1
        return d
    def nth_bd(n, start=None):
        return add_bd(start or today, n)
    def monday_of(d):
        return d - datetime.timedelta(days=d.weekday())
    def last_bd_of_week(monday):
        best = None
        for i in range(7):
            x = monday + datetime.timedelta(days=i)
            if isbd(x):
                best = x
        return best
    def say(d):
        return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y')
    def full(d):
        return say(d) + ' (' + d.isoformat() + ')'
    def band_deadline(name):
        if name == 'band_1_15':
            return nth_bd(10)
        if name == 'band_16_30':
            return nth_bd(6)
        if name == 'band_31_60':
            return nth_bd(3)
        return today
    def attempt_date(n, deadline):
        if n == 1:
            return nextbd(today)
        if n == 2:
            return deadline
        return deadline
    def floor_expr_for(ptype, p, due):
        import math
        if ptype == 'overdraft':
            return float(math.ceil(due * 0.25))
        return None

    TYPES = [('credit_card', 'credit card ending <card_last4>', 'minimum_payment', 'minimum payment'), ('overdraft', 'current account overdraft', '', 'minimum'), ('personal_loan', 'personal loan', 'instalment_amount', 'instalment amount')]
    BANDS = [('band_1_15', 1, 15, 1), ('band_16_30', 16, 30, 2), ('band_31_60', 31, 60, 2)]
    ATTEMPTS = [(1, 'full', []), (2, 'floor', [])]
    FLOOR_SENTENCE = 'The lowest amount we can accept is the <floor_name> of <floor>; the rest remains overdue.'
    DEBT_TEMPLATE = 'Your <words> has <amount> overdue and is <days> days overdue.'
    DEBT_INTRO = 'Thank you, you are verified.'
    def type_info(p):
        for k, w, ff, fn in TYPES:
            if k == str(p.get('type')):
                return w, ff, fn
        return str(p.get('type')).replace('_', ' '), '', 'minimum amount'
    def fill(w, p):
        for k, v in p.items():
            w = w.replace('<' + str(k) + '>', str(v))
        return w
    facts = []
    debt = []
    ids = []
    for i, p in enumerate(prods):
        w, ff, fname = type_info(p)
        w = fill(w, p)
        due = num(p.get('past_due'))
        dl = int(num(p.get('days_late')))
        fx = floor_expr_for(str(p.get('type')), p, due)
        floor = fx if fx is not None else (num(p.get(ff)) if ff and p.get(ff) is not None else due)
        band = None
        for name, lo, hi, natt in BANDS:
            if lo <= dl <= hi:
                band = (name, natt)
                break
        if band is None:
            band = (BANDS[-1][0], BANDS[-1][3])
        deadline = band_deadline(band[0])
        pid = str(p.get('product_id'))
        ids.append(pid)
        debt.append(DEBT_TEMPLATE.replace('<words>', w).replace('<amount>', money(due)).replace('<days>', str(dl)))
        lines = ['PRODUCT ' + str(i + 1) + ': ' + w,
                 '  product_id: ' + pid + '  (copy exactly into tools)',
                 '  full past-due amount: ' + money(due) + ', days late: ' + str(dl) + ', band: ' + band[0].upper(),
                 '  floor (' + fname + '): ' + money(floor) + '. Never record less than this.',
                 '  DEADLINE (latest promise date): ' + full(deadline),
                 '  valid promise dates: business days from ' + iso(today) + ' to ' + iso(deadline) + ' included; no weekend, no holiday, nothing after the deadline.',
                 '  persuasion attempts allowed for this product: ' + str(band[1]) + '.']
        for n, amount, only in ATTEMPTS:
            if n > band[1] or (only and band[0] not in only):
                continue
            try:
                ad = attempt_date(n, deadline)
            except Exception:
                ad = deadline
            if ad is None or ad > deadline:
                ad = deadline
            if amount == 'floor':
                amt = 'the floor ' + money(floor)
            elif amount == 'full_or_floor':
                amt = 'the full amount ' + money(due) + ' (or the floor ' + money(floor) + ' if the customer already said the full amount is too much)'
            else:
                amt = 'the full amount ' + money(due)
            lines.append('  attempt ' + str(n) + ' offer: ' + amt + ' on ' + full(ad) + '.')
        if band[1] < len(ATTEMPTS):
            lines.append('  there is NO attempt ' + str(band[1] + 1) + ' for this product.')
        if FLOOR_SENTENCE:
            lines.append('  floor offer sentence: "' + FLOOR_SENTENCE.replace('<floor_name>', fname).replace('<floor>', money(floor)) + '"')
        # the model must never work out weekdays itself: list every valid promise date
        valid = [today + datetime.timedelta(days=k) for k in range(0, (deadline - today).days + 1) if isbd(today + datetime.timedelta(days=k))]
        lines.append('  EVERY valid promise date for this product (checked by code; any date not listed is invalid): ' + '; '.join(full(x) for x in valid))
        facts.append('\n'.join(lines))
    vars['account_facts'] = '\n\n'.join(facts)
    vars['product_count'] = str(len(prods))
    vars['product_ids'] = ', '.join(ids)
    vars['debt_lines'] = ((DEBT_INTRO + ' ') if DEBT_INTRO else '') + ' '.join(debt)
    vars['account_state'] = 'ok' if prods else 'error'
    vars['code_state'] = 'ok'
except Exception as e:
    vars['account_facts'] = 'Account details unavailable.'
    vars['debt_lines'] = ''
    vars['account_state'] = 'error'
    vars['code_error'] = str(e)[:200]

